CREATE TRIGGER IF NOT EXISTS exm_ms_marks_ai AFTER INSERT ON exm_marks WHEN NOT EXISTS(SELECT 1 FROM exams_mobile_sync_suppression WHERE record_key=NEW.organization_id||':marks:'||NEW.exam_id||':'||NEW.student_id||':'||NEW.subject_id) BEGIN INSERT INTO exams_mobile_sync_emit(organization_id,collection_key,record_id,operation,payload_json,changed_by) VALUES(NEW.organization_id,'marks',NEW.exam_id||':'||NEW.student_id||':'||NEW.subject_id,'upsert',json_object('id',NEW.id,'examId',NEW.exam_id,'examSubjectId',NEW.exam_subject_id,'studentId',NEW.student_id,'classId',NEW.class_id,'subjectId',NEW.subject_id,'marksObtained',NEW.marks_obtained,'isAbsent',NEW.is_absent,'isExempt',NEW.is_exempt,'percentage',NEW.percentage,'grade',NEW.grade,'gradePoints',NEW.grade_points,'remarks',NEW.remarks,'enteredBy',NEW.entered_by,'enteredAt',NEW.entered_at,'updatedAt',NEW.updated_at),NEW.entered_by);END;
